/**
 * Browser fixture Mod for the Stent API client assembly test: a plain Cordis
 * plugin that imports only the Stent client contract (`ctx.stentClient`) and
 * contributes a client command and a UI-slot registration. The assembly spec
 * boots it through the real Loader over the real browser command/slot
 * services and observes both contributions.
 */

export const name = 'stent-client-fixture-mod'
export const inject = ['stentClient']

export function apply(ctx) {
  ctx.stentClient.registerCommand({
    name: 'modclientcmd',
    description: 'fixture client command',
    available: () => true,
    ui: {
      kind: 'popupSelect',
      options: async () => [],
      onSelect: () => {},
    },
  })

  ctx.stentClient.registerSlot({ name: 'root' }, () => null)
}
